//! Gold: `family_census` is 1:1 with the live reference.
//!
//! `tests/fixtures/gold/family_census_v1.json` was generated by
//! `scripts/gold_family_census.py` — census cases render a real PDF and run
//! the reference's own `census_document` end to end, kernel cases call the
//! reference's pure functions. The inputs the port consumes travel in the
//! gold (page texts, extracted table grids) so this replays identical input.
//! The volatile keys (`source_path`, `document_sha256`) are stripped.
//!
//! The cases pin the traps the census exists for: the family-matrix device
//! table (parts-as-columns), the selection-guide table (parts-as-rows),
//! electrical-characteristics and absolute-maximum tables that must NOT read
//! as device tables, caption rows merged into grids, ordering-variant vs
//! single-OPN vs manual vs cpu-core verdicts, the no-text-layer instrument
//! failure, pin bogeys from package tokens, and the code-flash/data-flash
//! qualifier trap.

#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    reason = "gold tests assert on their own fixtures"
)]

use std::collections::BTreeMap;
use std::path::PathBuf;

use dw_recon::family_census::{
    above_opn_kind, attributes_in_label, census_document, classify_grain, classify_table,
    is_concrete_part_token, is_wildcard_token, packages_from_text, parts_from_text,
    stems_from_tokens, strip_title_rows, summarize, wildcards_from_text, GrainArgs, KindArgs,
    PageTables, SummaryRow,
};

fn gold_path() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("tests/fixtures/gold").is_dir() {
        assert!(dir.pop(), "could not locate tests/fixtures/gold");
    }
    dir.join("tests/fixtures/gold/family_census_v1.json")
}

fn gold() -> serde_json::Value {
    serde_json::from_str(&std::fs::read_to_string(gold_path()).unwrap()).unwrap()
}

fn page_tables(case: &serde_json::Value) -> Vec<PageTables> {
    let mut out = Vec::new();
    for entry in case["tables"].as_array().unwrap() {
        let page = entry["page"].as_i64().unwrap();
        let mut tables = Vec::new();
        for grid in entry["tables"].as_array().unwrap() {
            let mut rows = Vec::new();
            for row in grid.as_array().unwrap() {
                let mut cells = Vec::new();
                for cell in row.as_array().unwrap() {
                    cells.push(cell.as_str().map(str::to_string));
                }
                rows.push(cells);
            }
            tables.push(rows);
        }
        out.push(PageTables { page, tables });
    }
    out
}

fn raw_rows(value: &serde_json::Value) -> Vec<Vec<Option<String>>> {
    value
        .as_array()
        .unwrap()
        .iter()
        .map(|row| {
            row.as_array()
                .unwrap()
                .iter()
                .map(|cell| cell.as_str().map(str::to_string))
                .collect()
        })
        .collect()
}

fn lane_pages(case: &serde_json::Value) -> Option<BTreeMap<String, Vec<i64>>> {
    case["lane_pages"].as_object().map(|obj| {
        obj.iter()
            .map(|(k, v)| {
                (
                    k.clone(),
                    v.as_array()
                        .unwrap()
                        .iter()
                        .map(|n| n.as_i64().unwrap())
                        .collect(),
                )
            })
            .collect()
    })
}

#[test]
fn every_case_matches_the_live_reference() {
    let g = gold();
    let mut checked = 0;
    for case in g["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let got: serde_json::Value = match case["kind"].as_str().unwrap() {
            "census" => {
                let pages: Vec<String> = case["pages"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|p| p.as_str().unwrap().to_string())
                    .collect();
                let mut ours = census_document(
                    &pages,
                    &page_tables(case),
                    lane_pages(case).as_ref(),
                    case["registry_stems"].as_i64().unwrap(),
                    case["vendor"].as_str(),
                    case["category"].as_str(),
                );
                ours.source_path = Some(format!("/{name}.pdf"));
                ours.document_sha256 = Some("f".repeat(64));
                let mut got = serde_json::to_value(&ours).unwrap();
                for k in ["source_path", "document_sha256"] {
                    got.as_object_mut().unwrap().remove(k);
                }
                got
            }
            "classify_table" => {
                serde_json::to_value(classify_table(&raw_rows(&case["rows"]))).unwrap()
            }
            "strip_title_rows" => {
                serde_json::to_value(strip_title_rows(&raw_rows(&case["rows"]))).unwrap()
            }
            "is_wildcard_token" => {
                serde_json::to_value(is_wildcard_token(case["token"].as_str().unwrap())).unwrap()
            }
            "is_concrete_part_token" => {
                serde_json::to_value(is_concrete_part_token(case["token"].as_str().unwrap()))
                    .unwrap()
            }
            "wildcards_from_text" => {
                serde_json::to_value(wildcards_from_text(case["text"].as_str().unwrap())).unwrap()
            }
            "parts_from_text" => {
                let stems: Option<std::collections::BTreeSet<String>> =
                    case["stems"].as_array().map(|arr| {
                        arr.iter()
                            .map(|s| s.as_str().unwrap().to_string())
                            .collect()
                    });
                serde_json::to_value(parts_from_text(
                    case["text"].as_str().unwrap(),
                    stems.as_ref(),
                ))
                .unwrap()
            }
            "stems_from_tokens" => {
                let tokens: Vec<String> = case["tokens"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|t| t.as_str().unwrap().to_string())
                    .collect();
                serde_json::to_value(stems_from_tokens(tokens)).unwrap()
            }
            "packages_from_text" => {
                serde_json::to_value(packages_from_text(case["text"].as_str().unwrap())).unwrap()
            }
            "attributes_in_label" => {
                serde_json::to_value(attributes_in_label(case["label"].as_str().unwrap())).unwrap()
            }
            "classify_grain" => {
                let args: GrainArgs = serde_json::from_value(case["args"].clone()).unwrap();
                serde_json::to_value(classify_grain(&args)).unwrap()
            }
            "above_opn_kind" => {
                let args: KindArgs = serde_json::from_value(case["args"].clone()).unwrap();
                serde_json::to_value(above_opn_kind(&args)).unwrap()
            }
            "summarize" => {
                let rows: Vec<SummaryRow> = serde_json::from_value(case["rows"].clone()).unwrap();
                serde_json::to_value(summarize(&rows)).unwrap()
            }
            other => panic!("unknown gold case kind {other}"),
        };
        assert_eq!(got, case["expected"], "case {name}");
        checked += 1;
    }
    assert_eq!(checked, g["cases"].as_array().unwrap().len());
}
